function render(){const state=readRoute();lang=state.lang;route=state.route||'home';mobileOpen=false;shell();const main=byId('main-content');if(route==='home')main.innerHTML=homePage();else if(route==='properties')main.innerHTML=propertiesPage();else if(route.startsWith('property/'))main.innerHTML=detailPage(route.split('/')[1]);else if(route==='about')main.innerHTML=aboutPage();else if(route==='services')main.innerHTML=servicesPage();else if(route==='team')main.innerHTML=teamPage();else if(route==='contact')main.innerHTML=contactPage();else main.innerHTML=homePage();if(route==='properties')bindFilters();if(route==='home'){bindCarousel();bindHeroVideo();bindFeaturedVideo()}else{heroScrubCleanup?.();heroScrubCleanup=null;featuredScrubCleanup?.();featuredScrubCleanup=null}if(route==='home'||route==='about')bindAboutVideo();else{aboutScrubCleanup?.();aboutScrubCleanup=null}if(route.startsWith('property/'))bindGallery();bindForms();if(scrollPos){window.scrollTo({top:scrollPos,behavior:'instant'});scrollPos=0}else window.scrollTo({top:0,behavior:'instant'});byId('site-header').classList.toggle('scrolled',scrollY>35);const label=route.startsWith('property/')?txt(raw.find(p=>p.slug===route.split('/')[1])?.name||{en:'Property',fa:'ملک'}):t('nav')[Math.max(0,t('navIds').indexOf(route))]||'Horizon Properties';document.title=`${label} | Horizon Properties`;}
function bindFilters(){const form=byId('filter-form');const results=byId('results-grid'),count=byId('property-count');function apply(){const f=new FormData(form),q=String(f.get('q')||'').toLocaleLowerCase(),loc=f.get('location'),type=f.get('type'),max=Number(f.get('maxPrice')||Infinity),beds=Number(f.get('beds')||0),sort=f.get('sort');let items=raw.filter(p=>(!q||`${txt(p.name)} ${txt(p.location)}`.toLocaleLowerCase().includes(q))&&(!loc||txt(p.location).startsWith(loc))&&(!type||txt(p.type)===type)&&p.price<=max&&p.beds>=beds);if(sort==='price-asc')items.sort((a,b)=>a.price-b.price);if(sort==='price-desc')items.sort((a,b)=>b.price-a.price);if(sort==='newest')items.sort((a,b)=>b.year-a.year);count.textContent=`${num(items.length)} ${t('showing')}`;results.innerHTML=items.length?items.map(p=>card(p,p.featured)).join(''):`<div class="empty-state">${t('noResults')}</div>`}form.addEventListener('input',apply);form.addEventListener('change',apply);form.addEventListener('submit',e=>{e.preventDefault();apply()});apply()}
