function bindGallery(){lightboxImages=raw.find(p=>p.slug===route.split('/')[1])?.gallery.map(x=>A+x)||[];document.querySelectorAll('[data-gallery]').forEach(b=>b.addEventListener('click',()=>openLightbox(Number(b.dataset.gallery))))}
function openLightbox(index){lastFocus=document.activeElement;lightboxIndex=index;updateLightbox();byId('lightbox').classList.add('open');byId('lightbox').setAttribute('aria-hidden','false');document.body.style.overflow='hidden';byId('lightbox').querySelector('.lightbox-close').focus()}
function updateLightbox(){const box=byId('lightbox');box.querySelector('img').src=lightboxImages[lightboxIndex];box.querySelector('img').alt=`${lang==='fa'?'تصویر':'Image'} ${lightboxIndex+1}`;box.querySelector('.lightbox-count').textContent=`${lightboxIndex+1} / ${lightboxImages.length}`}
function closeLightbox(){byId('lightbox').classList.remove('open');byId('lightbox').setAttribute('aria-hidden','true');document.body.style.overflow='';if(lastFocus)lastFocus.focus()}
function bindForms(){const nl=byId('newsletter-form');if(nl)nl.addEventListener('submit',e=>{e.preventDefault();const email=new FormData(nl).get('email');let list=[];try{list=JSON.parse(localStorage.getItem('horizon-newsletter')||'[]')}catch{}if(email&&!list.includes(email))list.push(email);localStorage.setItem('horizon-newsletter',JSON.stringify(list));byId('newsletter-note').textContent=t('newsletterSent');nl.reset()});const form=byId('contact-form');if(form)form.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(form),subject=encodeURIComponent(`Horizon Properties — ${f.get('interest')||t('contactUs')}`),body=encodeURIComponent(`${t('name')}: ${f.get('name')}\n${t('email')}: ${f.get('email')}\n${t('phone')}: ${f.get('phone')||'—'}\n\n${f.get('message')}`);byId('contact-note').textContent=t('sent');location.href=`mailto:hello@horizonproperties.com?subject=${subject}&body=${body}`})}
